tic
[f1,r_load1,V_bias1,R_load1] = IEEE123function1_plus(idx,vals);
[f2,r_load2,V_bias2,R_load2] = IEEE123function2_plus(idx,vals);
[f3,r_load3,V_bias3,R_load3] = IEEE123function3_plus(idx,vals);
